<script>
 import { tick } from 'svelte';
 import './disk-native.css';
 let { state: nativeMigrationAssistantState, windowId, profile, controller, execute, registerView } = $props();
 let root = $state(), scroller = $state(), feedback = $state(''), sourceRootId = $state(''), destinationRootId = $state(''), collision = $state('keepBoth');
 let session = $derived(nativeMigrationAssistantState.sessions.find(row => row.windowId === windowId));
 let windows = $derived(profile.id.startsWith('windows'));
 let classic = $derived(/high-sierra|mojave/.test(profile.id));
 let sources = $derived.by(() => { void nativeMigrationAssistantState; void session; return controller.getSources(); });
 let files = $derived.by(() => { void nativeMigrationAssistantState; void session; return controller.getFiles(); });
 let volumes = $derived.by(() => { void nativeMigrationAssistantState; void session; return controller.getVolumes(); });
 let source = $derived(sources.find(row => row.rootFileId === session?.sourceRootId));
 let destination = $derived(volumes.find(row => row.rootFileId === session?.destinationRootId));
 let sourceFiles = $derived.by(() => { const byId = new Map(files.map(file => [file.id, file])); return files.filter(file => { if (file.id === session?.sourceRootId) return false; const seen = new Set(); let current = file; while (current && !seen.has(current.id)) { if (current.parentId === session?.sourceRootId) return true; seen.add(current.id); current = byId.get(current.parentId); } return false; }); });
 const categories = [['documents','Documents'],['desktop','Desktop'],['pictures','Pictures'],['users','User accounts']];
 async function send(command, payload = {}) { try { const result = await execute(command, { windowId }, payload); feedback = result?.status === 'rejected' ? result.error?.message ?? 'Migration could not proceed.' : ''; return result; } catch (error) { feedback = error.message; } }
 async function next() { if (session.stage === 'source') { const result = await send('migration.source', { sourceRootId, destinationRootId }); if (result?.status !== 'applied') return; } await send('migration.next'); }
 function toggleCategory(id, checked) { const selected = new Set(session.categories); checked ? selected.add(id) : selected.delete(id); void send('migration.selection', { categories: [...selected], fileIds: session.fileIds }); }
 function toggleFile(id, checked) { const selected = new Set(session.fileIds); checked ? selected.add(id) : selected.delete(id); void send('migration.selection', { fileIds: [...selected], categories: session.categories }); }
 $effect(() => { sourceRootId = session?.sourceRootId ?? ''; destinationRootId = session?.destinationRootId ?? ''; });
 $effect(() => {
  const original = root, originalScroller = scroller, originalSession = session; if (!original || !originalScroller || !originalSession) return;
  let retired = false;
  const available = () => !retired && root === original && scroller === originalScroller && original.isConnected && nativeMigrationAssistantState.sessions.find(row => row.windowId === windowId) === originalSession;
  const find = (attribute, id) => [...original.querySelectorAll(`[${attribute}]`)].find(node => node.getAttribute(attribute) === id && node.getClientRects().length && !node.disabled && !node.closest('[inert]'));
  const reject = () => ({ status: 'rejected', error: { code: 'stale_target', message: 'The original mounted Migration Assistant view is unavailable.' } });
  const view = { available, describe: () => available() ? { windowId, controlIds: [...original.querySelectorAll('[data-migration-control]')].map(node => node.dataset.migrationControl), areaIds: ['content'] } : null,
   async focus(target, guard = () => true) { const controlId = typeof target === 'string' ? target : target.controlId, node = find('data-migration-control', controlId); if (!available() || guard() !== true || !node) return reject(); node.focus(); await tick(); return available() && guard() === true && find('data-migration-control', controlId) === node && node.ownerDocument.activeElement === node ? { status: 'applied', controlId } : reject(); },
   async scroll({ areaId = 'content', top = 0, left = 0 }, guard = () => true) { const node = find('data-migration-area', areaId); if (!available() || guard() !== true || !node) return reject(); node.scrollTo({ top, left, behavior: 'instant' }); await tick(); return available() && guard() === true && find('data-migration-area', areaId) === node ? { status: 'applied', areaId, top: node.scrollTop, left: node.scrollLeft } : reject(); }, destroy() { retired = true; } };
  const unregister = registerView(windowId, view); return () => { view.destroy(); if (typeof unregister === 'function') unregister(); };
 });
</script>

{#if session}
<section bind:this={root} class="disk-native disk-wizard migration-wizard" class:disk-classic={classic} class:disk-windows={windows} aria-label="Migration Assistant">
 {#if windows}<p class="disk-disclosure">Functional local Migration Assistant equivalent, not Windows Easy Transfer. Files and local account metadata are copied only inside this scene.</p>{:else if profile.id.includes('golden-gate')}<p class="disk-disclosure">macOS 27 native appearance unverified; nearest macOS 26-inspired presentation.</p>{/if}
 <main bind:this={scroller} class="disk-wizard-content" data-migration-area="content" tabindex="0">
  <div class="migration-illustration" aria-hidden="true"><svg viewBox="0 0 260 110"><defs><linearGradient id={`migration-screen-${windowId}`} x2="0" y2="1"><stop stop-color="#66c9ed"/><stop offset="1" stop-color="#225b99"/></linearGradient></defs><path d="M95 50H163" stroke="#bbb" stroke-width="4"/><path d="m139 38 15 12-15 12" fill="none" stroke="#777" stroke-width="3"/><g fill="#d6d8da" stroke="#777"><rect x="12" y="13" width="83" height="60" rx="4"/><path d="M47 73h14v15H47zM31 89h47v4H31z"/><rect x="165" y="13" width="83" height="60" rx="4"/><path d="M200 73h14v15h-14zM184 89h47v4h-47z"/></g><g fill={`url(#migration-screen-${windowId})`}><rect x="17" y="18" width="73" height="47"/><rect x="170" y="18" width="73" height="47"/></g></svg></div>
  {#if session.stage === 'intro'}<h1>Migration Assistant</h1><p>Transfer information from another computer or a Time Machine backup.</p><p>This assistant copies actual local files and selected local user-account metadata to the destination you choose. It does not connect to another computer or change host accounts.</p><div class="disk-wizard-callout">Before transferring, choose a source and destination with enough available space.</div>
  {:else if session.stage === 'source'}<h1>Transfer Information to This Computer</h1><p>Select the computer volume or Time Machine backup to transfer from.</p><fieldset class="disk-source-list"><legend>Transfer from</legend>{#each sources as row}<label class="disk-source-card" class:chosen={sourceRootId === row.rootFileId}><input type="radio" name={`migration-source-${windowId}`} data-migration-control={`source:${row.id}`} value={row.rootFileId} bind:group={sourceRootId}/><span class:disk-backup-drive={row.kind === 'backup'} class="disk-small-drive" aria-hidden="true"></span><span><strong>{row.label}</strong><small>{row.kind === 'backup' ? 'Time Machine backup' : 'Computer volume'}</small></span></label>{/each}{#if !sources.length}<p>No live source volumes or available backup snapshots.</p>{/if}</fieldset><label>Transfer to<select data-migration-control="destination" bind:value={destinationRootId}><option value="">Choose destination volume</option>{#each volumes.filter(row => row.mounted && row.rootFileId !== sourceRootId) as row}<option value={row.rootFileId}>{row.name}</option>{/each}</select></label>
  {:else if session.stage === 'select'}<h1>Select the Information to Transfer</h1><p>From {source?.label ?? session.sourceRootId} to {destination?.name ?? session.destinationRootId}</p><fieldset class="disk-migration-categories"><legend>Categories</legend>{#each categories as [id,label]}<label><input type="checkbox" data-migration-control={`category:${id}`} checked={session.categories.includes(id)} onchange={event => toggleCategory(id,event.currentTarget.checked)}/>{label}</label>{/each}</fieldset><details class="disk-migration-files" open><summary>Choose individual files and folders ({sourceFiles.length})</summary>{#each sourceFiles as file}<label><input type="checkbox" data-migration-control={`file:${file.id}`} checked={session.fileIds.includes(file.id)} onchange={event => toggleFile(file.id,event.currentTarget.checked)}/><span>{file.name}<small>{file.kind === 'folder' ? 'Folder' : file.mime ?? 'Document'} · {file.id}</small></span></label>{/each}{#if !sourceFiles.length}<p>The selected source has no available files.</p>{/if}</details><p class="disk-local-note">Selected folders include their descendants. Categories and individual choices are combined by the transfer controller; user accounts refer to this scene’s account metadata only.</p>
  {:else if session.stage === 'ready'}<h1>Ready to Transfer</h1><dl class="disk-properties"><dt>From</dt><dd>{source?.label ?? session.sourceRootId}</dd><dt>To</dt><dd>{destination?.name ?? session.destinationRootId}</dd><dt>Categories</dt><dd>{session.categories.map(id => categories.find(row => row[0] === id)?.[1] ?? id).join(', ') || 'None'}</dd><dt>Individual choices</dt><dd>{session.fileIds.length}</dd></dl><label>When destination names already exist<select data-migration-control="collision" bind:value={collision}><option value="keepBoth">Keep both copies</option><option value="skip">Skip existing files</option><option value="replace">Replace existing files</option></select></label>{#if collision === 'replace'}<p class="disk-warning">Continuing replaces same-name destination files. Their previous contents cannot be recovered by this operation.</p>{/if}<p>Click Transfer to copy the selected information.</p>
  {:else if session.stage === 'running'}<h1>Transferring Your Information</h1><p>Copying from {source?.label ?? session.sourceRootId} to {destination?.name ?? session.destinationRootId}.</p><progress max="100" value={session.progress} aria-label="Migration progress"></progress><p>{session.progress}%</p>
  {:else if session.stage === 'complete'}<h1>Migration Complete</h1><p>{session.message}</p>{#if nativeMigrationAssistantState.users?.length}<h2>Local account metadata</h2><ul class="disk-account-list">{#each nativeMigrationAssistantState.users as user}<li><strong>{user.name ?? user.username ?? user.id}</strong><small>{user.id}</small></li>{/each}</ul>{/if}<p>The transferred information is available in the destination’s actual Files tree. No host users were created.</p>{/if}
  {#if feedback}<p class="disk-error" role="alert">{feedback}</p>{/if}<p class="disk-wizard-message" role="status">{session.stage !== 'complete' ? session.message : ''}</p>
 </main>
 <footer class="disk-wizard-footer"><span class="disk-step-indicator">{['intro','source','select','ready','running','complete'].indexOf(session.stage) + 1} of 6</span><button data-migration-control="cancel" onclick={() => send('migration.cancel')}>{session.stage === 'running' ? 'Cancel Transfer' : 'Cancel'}</button><button data-migration-control="back" disabled={session.stage === 'intro' || session.stage === 'running'} onclick={() => send('migration.back')}>Go Back</button>{#if session.stage === 'ready'}<button class="disk-default" data-migration-control="transfer" onclick={() => send('migration.start', { collision })}>Transfer</button>{:else if session.stage !== 'running' && session.stage !== 'complete'}<button class="disk-default" data-migration-control="continue" disabled={(session.stage === 'source' && (!sourceRootId || !destinationRootId || sourceRootId === destinationRootId)) || (session.stage === 'select' && !session.fileIds.length && !session.categories.length)} onclick={next}>Continue</button>{/if}</footer>
</section>
{/if}
